// Extrair dados do payload
const body = JSON.parse($input.first().json.body);

const { question_id, student_response, question_text, scenario_context, competency, level, rubric } = body;

// Montar system prompt baseado no nível
const levelContexts = {
  1: 'NÍVEL 1 - FUNDAMENTOS (R$ 3-8k). Avalie como recepcionista iniciante. Tolere alguma insegurança técnica, mas NÃO tolere desrespeito ou pressão.',
  2: 'NÍVEL 2 - HIGH TICKET (R$ 10-25k). Avalie como consultora experiente. Espere domínio de descoberta multinível e ancoragem de valor.',
  3: 'NÍVEL 3 - PREMIUM (R$ 25-80k+). Avalie postura peer-to-peer com CEOs e celebridades. NÃO tolere intimidação ou servilismo.',
  4: 'NÍVEL 4 - LTV (R$ 100-500k+). Avalie gestão de relacionamento vitalício. Espere pensamento de longo prazo e cálculo de LTV.'
};

const systemPrompt = `Você é avaliador especialista em vendas consultivas de cirurgia plástica no Brasil.

${levelContexts[level] || levelContexts[1]}

Rubrica específica: ${rubric || 'Avalie rapport, descoberta, apresentação, objeções e fechamento.'}

RESPONDA EXCLUSIVAMENTE em JSON válido, sem texto adicional:
{
  "score": <0-10>,
  "competency_scores": {"principal": <0-10>, "secundaria": <0-10>},
  "feedback": "<2-3 frases construtivas>",
  "what_was_good": "<ponto positivo>",
  "what_to_improve": "<melhoria sugerida>",
  "ideal_response": "<resposta modelo>"
}`;

const userMessage = `CENÁRIO: ${scenario_context}\n\nPERGUNTA: ${question_text}\n\nRESPOSTA DO ALUNO:\n"${student_response}"\n\nCOMPETÊNCIA AVALIADA: ${competency}\n\nAvalie em JSON.`;

return [{
  json: {
    question_id,
    systemPrompt,
    userMessage,
    student_response,
    competency,
    level
  }
}];

const input = $input.first().json;
const prevData = $('Preparar Prompt').first().json;

try {
  // Extrair texto da resposta do Claude
  const content = input.content?.[0]?.text || '';

  // Limpar possíveis markdown fences
  const cleaned = content.replace(/```json|```/g, '').trim();
  const evaluation = JSON.parse(cleaned);

  return [{
    json: {
      success: true,
      question_id: prevData.question_id,
      competency: prevData.competency,
      level: prevData.level,
      student_response: prevData.student_response,
      evaluation: {
        score: Math.min(10, Math.max(0, evaluation.score)),
        competency_scores: evaluation.competency_scores || {},
        feedback: evaluation.feedback || 'Avaliação concluída.',
        what_was_good: evaluation.what_was_good || '',
        what_to_improve: evaluation.what_to_improve || '',
        ideal_response: evaluation.ideal_response || ''
      },
      model_used: 'claude-sonnet-4-20250514',
      evaluated_at: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      question_id: prevData.question_id,
      error: 'Falha ao processar avaliação: ' + error.message,
      raw_response: input.content?.[0]?.text || 'sem resposta'
    }
  }];
}

const body = JSON.parse($input.first().json.body);
const { level, competency, procedure } = body;

const systemPrompt = `Você é especialista em criação de cenários de treinamento para vendas em clínicas de cirurgia plástica premium no Brasil.

Gere EXATAMENTE em JSON válido sem texto adicional:
{
  "patient_name": "nome brasileiro",
  "patient_age": numero,
  "patient_profession": "profissão",
  "scenario": "contexto em 3 frases",
  "patient_says": "fala da paciente",
  "question": "pergunta avaliativa",
  "options": [
    {"text": "opcao A", "score": 0-10, "feedback": "explicacao"},
    {"text": "opcao B", "score": 0-10, "feedback": "explicacao"},
    {"text": "opcao C", "score": 0-10, "feedback": "explicacao"}
  ],
  "competency": "${competency}",
  "ideal_response": "resposta modelo"
}

REGRAS: cenários AMBÍGUOS, duas opções parecem boas, linguagem brasileira real, variar perfis.`;

const userMessage = `Gere cenário nível ${level}, competência ${competency}, procedimento ${procedure || 'variado'}.`;

return [{ json: { systemPrompt, userMessage, level, competency, procedure } }];

const input = $input.first().json;
try {
  const text = input.content?.[0]?.text || '';
  const cleaned = text.replace(/```json|```/g, '').trim();
  const scenario = JSON.parse(cleaned);
  return [{ json: { success: true, scenario, generated_at: new Date().toISOString() } }];
} catch (e) {
  return [{ json: { success: false, error: e.message } }];
}
